#!/usr/bin/env bash
# Build whisper.cpp (the checkout in WHISPER_DIR) in Release mode: scripts/build.sh [--clean]
# Metal and Accelerate are on by default on macOS. SDL2 (whisper-stream) is enabled when sdl2 is installed,
# Core ML when the encoder generated by scripts/coreml.sh is in the models directory.
# On an exact release tag the build is marked non-dev, so `whisper-cli --version` prints the plain version.
# shellcheck source=lib/common.sh
source "$(dirname "$0")/lib/common.sh"

need_checkout
need_tool cmake
if under_rosetta; then
  die "this terminal runs under Rosetta (x86_64): open a native arm64 terminal, or the build will be an Intel binary without Metal"
fi
on_apple_silicon || echo "warning: not on Apple Silicon ($(uname -s) $(uname -m)); the build is untested here and Metal needs an Apple GPU" >&2
if [ "${1:-}" = "--clean" ]; then
  echo "removing $whisper_build"
  rm -rf "$whisper_build"
fi

sdl2=OFF
command -v sdl2-config >/dev/null && sdl2=ON
dev=ON
whisper_on_tag && dev=OFF
# Core ML stays on across builds and rebuilds as long as the encoder made by `just coreml` is next to the model.
coreml=OFF
[ -d "$WHISPER_MODELS_DIR/ggml-$WHISPER_MODEL-encoder.mlmodelc" ] && coreml=ON

echo "building whisper.cpp $(whisper_version) (dev build: $dev, sdl2: $sdl2, coreml: $coreml)"
cmake -S "$WHISPER_DIR" -B "$whisper_build" -DCMAKE_BUILD_TYPE=Release -DWHISPER_SDL2="$sdl2" -DWHISPER_BUILD_IS_DEV="$dev" -DWHISPER_COREML="$coreml"
cmake --build "$whisper_build" -j --config Release
for bin in cli stream bench server; do
  [ -x "$whisper_build/bin/whisper-$bin" ] && echo "whisper-$bin"
done
"$whisper_cli" --version
